void pre(int i)
{
    int a[] = {8, 3, 10};
    if (i >= 3) {
        return;
    }
    printf("%d ", a[i]);
    pre(2 * i + 1);
    pre(2 * i + 2);
}
int main(void)
{
    pre(0);
    puts("");
